import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome210 {
    data class Success(val payload: String) : Outcome210()
    data object Failure : Outcome210()
}

fun describe210(outcome: Outcome210): String = when (outcome) {
    is Outcome210.Success -> outcome.payload
    Outcome210.Failure -> "failed"
}
